def lis(a):
    d=[1]*len(a)
    for i in range(len(a)):
        for j in range(i):
            if a[j]<a[i]:d[i]=max(d[i],d[j]+1)
    return max(d,default=0)
def inv(a): return sum(a[i]>a[j] for i in range(len(a)) for j in range(i+1,len(a)))
def kadane(a):
    best=cur=a[0]
    for x in a[1:]:cur=max(x,cur+x);best=max(best,cur)
    return best
def nonadj(a):
    p=q=0
    for x in a:p,q=q,max(q,p+x)
    return q
def water(a):return sum(max(0,min(max(a[:i+1]),max(a[i:]))-x) for i,x in enumerate(a))
def span(a):
    out=[]
    for i,x in enumerate(a):
        j=i-1
        while j>=0 and a[j]<=x:j-=1
        out.append(i-j)
    return out
def nextgreater(a):return [next((y for y in a[i+1:] if y>x),-1) for i,x in enumerate(a)]
def lis_java():return 'int[] d=new int[a.length]; Arrays.fill(d,1); int best=0; for(int i=0;i<a.length;i++){for(int j=0;j<i;j++)if(a[j]<a[i])d[i]=Math.max(d[i],d[j]+1);best=Math.max(best,d[i]);}System.out.println(best);'
