def paren_depth(s):
    d=best=0
    for c in s:
        if c=='(':d+=1;best=max(best,d)
        if c==')':d-=1
        if d<0:return -1
    return best if d==0 else -1
def fib(n):
    a,b=0,1
    for _ in range(n):a,b=b,a+b
    return a
def coins(n):
    d=[0]+[999]*n
    for i in range(1,n+1):d[i]=1+min(d[i-c] for c in (1,3,4) if c<=i)
    return d[n]
