def bst_height(a):
    def ins(t,x):
        if t is None:return [x,None,None]
        if x<t[0]:t[1]=ins(t[1],x)
        if x>t[0]:t[2]=ins(t[2],x)
        return t
    def h(t):return 0 if t is None else 1+max(h(t[1]),h(t[2]))
    t=None
    for x in a:t=ins(t,x)
    return h(t)
def longest_consecutive(a):
    s=set(a)
    return max((next((k for k in range(1,len(s)+1) if x+k not in s),len(s)) for x in s if x-1 not in s),default=0)

def graph_reach(a):
    n=a[0];edges=list(zip(a[2::2],a[3::2]));adj=[[] for _ in range(n)]
    for u,v in edges:adj[u].append(v)
    seen={0};q=[0]
    for u in q:
        for v in adj[u]:
            if v not in seen:seen.add(v);q.append(v)
    return len(seen)
def graph_distance(a):
    n=a[0];edges=list(zip(a[2::2],a[3::2]));adj=[[] for _ in range(n)]
    for u,v in edges:adj[u].append(v)
    d=[-1]*n;d[0]=0;q=[0]
    for u in q:
        for v in adj[u]:
            if d[v]<0:d[v]=d[u]+1;q.append(v)
    return d
def components(a):
    n=a[0];parent=list(range(n))
    def find(v):
        while parent[v]!=v:v=parent[v]
        return v
    for u,v in zip(a[2::2],a[3::2]):parent[find(u)]=find(v)
    return len(set(find(v) for v in range(n)))
def topo(a):
    n=a[0];adj=[[] for _ in range(n)];deg=[0]*n
    for u,v in zip(a[2::2],a[3::2]):adj[u].append(v);deg[v]+=1
    q=[v for v in range(n) if deg[v]==0];order=[]
    while q:
        q.sort();u=q.pop(0);order.append(u)
        for v in adj[u]:
            deg[v]-=1
            if deg[v]==0:q.append(v)
    return order if len(order)==n else 'CYCLE'
